import{_ as a}from"./chunks/ScenarioFitAssessment.CuCMhGwF.js";import{o as s,c as i,j as t,a as o,E as n,a3 as r}from"./chunks/framework.BPaanrMb.js";const h=JSON.parse('{"title":"Autonomous Driving Scenario Fit Assessment","description":"Assess short-distance transport opportunities across demand, routes, vehicle and cargo, safety and compliance, and economics.","frontmatter":{"title":"Autonomous Driving Scenario Fit Assessment","description":"Assess short-distance transport opportunities across demand, routes, vehicle and cargo, safety and compliance, and economics.","status":"design guidance","content_type":"assessment","keywords":["scenario assessment","autonomous-driving fit","fixed routes","safety compliance","economics","pilot"],"scope":"Initial suitability screening for enterprise short-distance autonomous transport projects","decision_summary":"After completing five gates, the tool returns a local recommendation to proceed to site assessment, collect more information, or defer deployment.","best_for":["frequent fixed routes","a clear operating owner","manageable sites","estimable operating cost"],"not_for":["unresolved compliance responsibility","infrequent transport","no clear owner or budget","autonomous driving as a demonstration only"],"next_action":"Complete the five steps, print or copy the summary, then decide whether to start a site survey.","cta_url":"mailto:support@wheelos.cn?subject=WheelOS%20scenario%20fit%20assessment","layout":"doc","sidebar":false,"aside":false,"outline":[2,3]},"headers":[],"relativePath":"en/solutions/fit-assessment.md","filePath":"en/solutions/fit-assessment.md","lastUpdated":1794551845000}'),l={name:"en/solutions/fit-assessment.md"},p=Object.assign(l,{setup(d){return(c,e)=>(s(),i("div",null,[e[0]||(e[0]=t("h1",{id:"autonomous-driving-scenario-fit-assessment",tabindex:"-1"},[o("Autonomous Driving Scenario Fit Assessment "),t("a",{class:"header-anchor",href:"#autonomous-driving-scenario-fit-assessment","aria-label":'Permalink to "Autonomous Driving Scenario Fit Assessment"'},"​")],-1)),e[1]||(e[1]=t("blockquote",null,[t("p",null,"Decide whether the transport task is worth solving before selecting a vehicle or system. This tool runs entirely in your browser and does not upload your answers.")],-1)),n(a),e[2]||(e[2]=r('<h2 id="static-decision-summary" tabindex="-1">Static decision summary <a class="header-anchor" href="#static-decision-summary" aria-label="Permalink to &quot;Static decision summary&quot;">​</a></h2><p>Even without the interactive tool, check these five areas first:</p><table tabindex="0"><thead><tr><th>Gate</th><th>Core question</th><th>Decision impact</th></tr></thead><tbody><tr><td>Transport demand</td><td>Is the work long-term, repetitive, stable and already consuming drivers or vehicles?</td><td>One-off or low-frequency demand rarely supports a viable case</td></tr><tr><td>Route conditions</td><td>Are origins, destinations, corridors, loading areas and handoffs clear and manageable?</td><td>Complex mixed traffic and uncertain handoffs raise project risk</td></tr><tr><td>Vehicle and cargo</td><td>Are weight, dimensions, temperature, loading and system interfaces understood?</td><td>Non-standard cargo requires additional vehicle or process design</td></tr><tr><td>Safety and compliance</td><td>Are access, permits, safety responsibility, insurance and exceptions resolved?</td><td>Do not enter commercial deployment while critical responsibility is unresolved</td></tr><tr><td>Economics</td><td>Are current cost, full deployment cost and productive daily work estimable?</td><td>Compare total cost with the existing transport method, not only autonomous features</td></tr></tbody></table><h2 id="complete-assessment-checklist" tabindex="-1">Complete assessment checklist <a class="header-anchor" href="#complete-assessment-checklist" aria-label="Permalink to &quot;Complete assessment checklist&quot;">​</a></h2><h3 id="transport-demand" tabindex="-1">Transport demand <a class="header-anchor" href="#transport-demand" aria-label="Permalink to &quot;Transport demand&quot;">​</a></h3><ul><li>[ ] The transport task exists long-term rather than as a one-off need.</li><li>[ ] There is a relatively stable daily or weekly transport frequency.</li><li>[ ] Origins, destinations and primary tasks are clear.</li><li>[ ] Drivers, vehicles or dispatch resources are currently committed.</li></ul><h3 id="route-conditions" tabindex="-1">Route conditions <a class="header-anchor" href="#route-conditions" aria-label="Permalink to &quot;Route conditions&quot;">​</a></h3><ul><li>[ ] The route is relatively fixed with clear origins and destinations.</li><li>[ ] Roads and operating areas are passable for the intended vehicle.</li><li>[ ] Loading and handoff locations are relatively fixed.</li><li>[ ] Mixed traffic, junctions and temporary obstacles can be assessed and managed.</li></ul><h3 id="vehicle-and-cargo" tabindex="-1">Vehicle and cargo <a class="header-anchor" href="#vehicle-and-cargo" aria-label="Permalink to &quot;Vehicle and cargo&quot;">​</a></h3><ul><li>[ ] Cargo weight, dimensions and transport requirements are defined.</li><li>[ ] Vehicle payload and cargo space satisfy the requirement.</li><li>[ ] Temperature, insulation or sealing requirements are defined with a viable solution.</li><li>[ ] Loading and handoff processes can be standardized.</li><li>[ ] The need to connect warehouse or dispatch systems is understood.</li></ul><h3 id="safety-and-compliance" tabindex="-1">Safety and compliance <a class="header-anchor" href="#safety-and-compliance" aria-label="Permalink to &quot;Safety and compliance&quot;">​</a></h3><ul><li>[ ] The operating area and access requirements are defined.</li><li>[ ] Operating permits, site management and safety responsibility can be assigned.</li><li>[ ] Exception handling, emergency stop and site-response procedures can be implemented.</li><li>[ ] Insurance and incident responsibility are defined.</li><li>[ ] Special-cargo requirements can be met or explicitly excluded.</li></ul><h3 id="economics" tabindex="-1">Economics <a class="header-anchor" href="#economics" aria-label="Permalink to &quot;Economics&quot;">​</a></h3><ul><li>[ ] The current driver, vehicle and transport-service cost is understood.</li><li>[ ] Vehicle, system, deployment, maintenance and operating costs can be estimated.</li><li>[ ] Daily productive work can support the investment.</li><li>[ ] A business owner, budget and willingness to cooperate are present.</li></ul><h2 id="common-cases-for-deferring-deployment" tabindex="-1">Common cases for deferring deployment <a class="header-anchor" href="#common-cases-for-deferring-deployment" aria-label="Permalink to &quot;Common cases for deferring deployment&quot;">​</a></h2><ul><li>The task is a short-term demonstration without stable utilization.</li><li>No operating owner, budget or long-term plan exists.</li><li>Routes, loading or handoffs are highly uncertain.</li><li>Regulation, insurance or safety responsibility remains unresolved.</li><li>Special-cargo requirements cannot be met and no alternative exists.</li><li>The customer focuses only on “driverless” without a business metric.</li></ul><h2 id="after-the-assessment" tabindex="-1">After the assessment <a class="header-anchor" href="#after-the-assessment" aria-label="Permalink to &quot;After the assessment&quot;">​</a></h2><ul><li><strong>Proceed to site assessment:</strong> review the vehicle, chassis, route, site and acceptance metrics.</li><li><strong>Information is incomplete:</strong> collect critical data before purchasing a vehicle.</li><li><strong>Not ready for deployment yet:</strong> resolve demand, route, safety or economic blockers first.</li></ul><p><a href="/en/solutions/delivery-process">View the path from requirements to pilot deployment →</a></p><div class="solution-cta"><div><h2>Want to review a real transport task with us?</h2><p>Send the cargo, origin and destination, frequency, vehicle and current transport method for an initial fit review.</p></div><div class="solution-actions"><a class="primary" href="mailto:support@wheelos.cn?subject=WheelOS%20scenario%20fit%20assessment">Send the scenario summary</a><a href="/en/solutions/applications">Explore six applications</a></div></div>',20))]))}});export{h as __pageData,p as default};
